/* ============================================
   DATE INPUT COMPONENT
   Date input with calendar icon and label
   ============================================ */

.ds-date-input {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200); /* 8px */
  width: 100%;
}

/* ============================================
   LABEL
   ============================================ */

/* ============================================
   FIELD WRAPPER
   ============================================ */

.ds-date-input__field-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

/* ============================================
   ICON
   ============================================ */

.ds-date-input__icon {
  position: absolute;
  left: var(--padding-400); /* 16px */
  top: 50%;
  transform: translateY(-50%);
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  pointer-events: none;
}

/* ============================================
   FIELD
   ============================================ */

.ds-date-input__field {
  width: 100%;
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  padding-left: calc(var(--padding-400) + 24px + var(--gap-200)); /* 16px + 24px icon + 8px gap */
  border: var(--border-025) solid var(--color-input-border-primary);
  border-radius: var(--radius-300); /* 12px */
  background-color: var(--color-input-bg-primary);

  /* Typography */
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-input-text-primary);

  /* Transitions */
  transition: border-color var(--motion-duration-base) var(--motion-ease-standard), background-color var(--motion-duration-base) var(--motion-ease-standard);
  outline: none;
}

/* Hide the default calendar icon in WebKit browsers */
.ds-date-input__field::-webkit-calendar-picker-indicator {
  opacity: 0;
  cursor: pointer;
}

.ds-date-input__field:hover:not(:focus):not(:disabled) {
  border-color: var(--color-input-border-hover);
}

.ds-date-input__field:focus {
  border-color: var(--color-input-border-selected);
  background-color: var(--color-input-bg-primary);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-date-input--compact .ds-date-input__field {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  padding-left: calc(var(--padding-300) + 20px + var(--gap-200)); /* 12px + 20px icon + 8px gap */
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-date-input--compact .ds-date-input__icon {
  left: var(--padding-300); /* 12px */
  --icon-size: var(--icon-size-500);
}

/* ============================================
   HELPER TEXT
   ============================================ */

/* ============================================
   ERROR STATE
   ============================================ */

.ds-date-input--error .ds-date-input__field {
  border-color: var(--color-status-error-border);
}

.ds-date-input--error .ds-date-input__field:focus {
  border-color: var(--color-status-error-border);
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-date-input--disabled .ds-date-input__field {
  background-color: var(--color-input-bg-disabled);
  border-color: var(--color-input-border-disabled);
  color: var(--color-input-text-disabled);
  cursor: not-allowed;
}

.ds-date-input--disabled .ds-date-input__icon {
  color: var(--color-input-text-disabled);
}

'use client';

import React from 'react';
import { Field } from '../Field/Field';
import './DateInput.css';
import '../../fonts/material-symbols.css';

/** Props owned by DateInput itself — everything else falls through to the <input>. */
type DateInputOwnProps = {
  /** Input label text */
  label?: string;
  /** Current value (YYYY-MM-DD format) */
  value?: string;
  /** Component size (not the native character-width `size` attribute) */
  size?: 'default' | 'compact';
  /** Error state */
  error?: boolean;
  /** Helper or error message */
  helperText?: string;
  /** Minimum selectable date (YYYY-MM-DD) */
  min?: string;
  /** Maximum selectable date (YYYY-MM-DD) */
  max?: string;
  /**
   * Convenience callback receiving the value directly.
   * Fires alongside `onChange`, which keeps the standard React event signature
   * so form libraries work unmodified.
   */
  onValueChange?: (value: string) => void;
  /** Additional CSS classes — applied to the wrapper, not the <input> */
  className?: string;
  /**
   * Legacy accessible-name prop.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
};

export interface DateInputProps
  extends DateInputOwnProps,
    Omit<React.ComponentPropsWithoutRef<'input'>, keyof DateInputOwnProps | 'type'> {}

/**
 * Date input component with native date picker.
 * Uses the browser's built-in date input with custom styling,
 * calendar icon, label, and validation states.
 *
 * Forwards a ref to the underlying `<input type="date">` and spreads
 * unrecognised props onto it.
 */
export const DateInput = React.forwardRef<HTMLInputElement, DateInputProps>(
  (
    {
      label,
      value,
      placeholder,
      size = 'default',
      disabled = false,
      required = false,
      error = false,
      helperText,
      min,
      max,
      onChange,
      onValueChange,
      className = '',
      ariaLabel,
      name,
      id,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-date-input';

    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      error ? `${baseClass}--error` : '',
      disabled ? `${baseClass}--disabled` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      onChange?.(e);
      onValueChange?.(e.target.value);
    };

    const inputId = id || name || label?.toLowerCase().replace(/\s+/g, '-');

    return (
      <Field
        className={classes}
        label={label}
        helperText={helperText}
        error={error}
        required={required}
        disabled={disabled}
        size={size}
        id={inputId}
      >
        <div className={`${baseClass}__field-wrapper`}>
          <span className={`${baseClass}__icon material-symbols-rounded`} aria-hidden="true">
            calendar_today
          </span>
          <input
            {...rest}
            ref={ref}
            className={`${baseClass}__field`}
            type="date"
            id={inputId}
            name={name}
            value={value}
            placeholder={placeholder}
            disabled={disabled}
            required={required}
            min={min}
            max={max}
            aria-label={ariaLabel || rest['aria-label'] || label}
            aria-invalid={error}
            aria-describedby={helperText ? `${inputId}-helper` : rest['aria-describedby']}
            onChange={handleChange}
          />
        </div>
      </Field>
    );
  },
);

DateInput.displayName = 'DateInput';
